class Solution { fun rotateTheBox(box:Array<CharArray>):Array<CharArray>{val rows=box.size;val cols=box[0].size;for(row in 0 until rows){var empty=cols-1;for(col in cols-1 downTo 0)if(box[row][col]=='*')empty=col-1 else if(box[row][col]=='#'){box[row][col]='.';box[row][empty--]='#'}};val result=Array(cols){CharArray(rows)};for(row in 0 until rows)for(col in 0 until cols)result[col][rows-1-row]=box[row][col];return result} }
